-- 064: perpanjang 5 dialog lepas N2 (E1 program kaiwa-30d, Day 17): "Konsultasi Karier" (work),
-- "Meminta Kenaikan Gaji", "Meminta Maaf atas Kesalahan", "Negosiasi dengan Klien" (biz),
-- "Menanggapi Keluhan Pelanggan" (work); masing-masing 4 -> 10 baris. Judul, kategori, dan 4 baris
-- asli dipertahankan persis (disalin dari baris yang ada di DB); 6 baris baru ditambahkan di akhir.
-- romaji baris baru dihasilkan skrip dari hiragana. vocab_highlight ditulis ulang ke format glosarium
-- Fase D. Idempoten.
-- Jalankan: npm run seed:kaiwa -- --file 064_extend_kaiwa_lepas_n2_short.sql

INSERT INTO public.kaiwa_stories (level_id, title, category, lines, vocab_highlight, is_premium) VALUES
(4, 'Konsultasi Karier', 'work',
 '[{"speaker":"アリ","text":"将来、管理職を目指したいと考えているのですが、何が必要でしょうか。","reading":"しょうらい、かんりしょくをめざしたいとかんがえているのですが、なにがひつようでしょうか。","romaji":"Shourai, kanrishoku o mezashitai to kangaete iru no desu ga, nani ga hitsuyou deshou ka.","trans":"Ke depan saya ingin menargetkan posisi manajerial, apa yang diperlukan?"},{"speaker":"先輩","text":"まずはリーダーシップと、部下を育てる力が大切だね。","reading":"まずはリーダーシップと、ぶかをそだてるちからがたいせつだね。","romaji":"Mazu wa riidaashippu to, buka o sodateru chikara ga taisetsu da ne.","trans":"Pertama, kepemimpinan dan kemampuan membina bawahan itu penting."},{"speaker":"アリ","text":"なるほど。経験を積むしかないですね。","reading":"なるほど。けいけんをつむしかないですね。","romaji":"Naruhodo. Keiken o tsumu shika nai desu ne.","trans":"Begitu ya. Tidak ada cara lain selain menambah pengalaman."},{"speaker":"先輩","text":"その通り。焦らず頑張って。","reading":"そのとおり。あせらずがんばって。","romaji":"Sono toori. Aserazu ganbatte.","trans":"Betul sekali. Berjuanglah tanpa terburu-buru."},{"speaker":"アリ","text":"資格を取ることも、評価につながりますか。","reading":"しかくをとることも、ひょうかにつながりますか。","romaji":"Shikaku o torukoto mo, hyouka ni tsunagarimasu ka.","trans":"Apakah mengambil sertifikasi juga berpengaruh pada penilaian?"},{"speaker":"先輩","text":"もちろん。ただ、資格だけでなく、実際に成果を出すことが大事だよ。","reading":"もちろん。ただ、しかくだけでなく、じっさいにせいかをだすことがだいじだよ。","romaji":"Mochiron. Tada, shikaku dake de naku, jissai ni seika o dasukoto ga daiji dayo.","trans":"Tentu. Tapi bukan hanya sertifikasi, yang penting adalah benar-benar menunjukkan hasil."},{"speaker":"アリ","text":"今の仕事で、どんなことに力を入れればいいでしょうか。","reading":"いまのしごとで、どんなことにちからをいれればいいでしょうか。","romaji":"Ima no shigoto de, donna koto ni chikara o irereba ii deshou ka.","trans":"Dalam pekerjaan sekarang, sebaiknya saya mencurahkan tenaga pada hal apa?"},{"speaker":"先輩","text":"後輩の相談に乗ったり、会議で意見を出したりしてみたらどうかな。","reading":"こうはいのそうだんにのったり、かいぎでいけんをだしたりしてみたらどうかな。","romaji":"Kouhai no soudan ni nottari, kaigi de iken o dashitari shite mitara dou ka na.","trans":"Bagaimana kalau mencoba menampung curhat adik kelas atau menyampaikan pendapat di rapat?"},{"speaker":"アリ","text":"分かりました。まずは小さなことから始めてみます。","reading":"わかりました。まずはちいさなことからはじめてみます。","romaji":"Wakarimashita. Mazu wa chiisana koto kara hajimete mimasu.","trans":"Baik. Pertama-tama saya akan mencoba mulai dari hal kecil."},{"speaker":"先輩","text":"うん。困ったら、いつでも声をかけてね。","reading":"うん。こまったら、いつでもこえをかけてね。","romaji":"Un. Komattara, itsudemo koe o kakete ne.","trans":"Ya. Kalau kesulitan, kapan saja bilang saja ya."}]'::jsonb,
 '[{"word":"管理職","reading":"かんりしょく · Kanrishoku","meaning":"posisi manajerial"},{"word":"部下","reading":"ぶか · Buka","meaning":"bawahan"},{"word":"経験を積む","reading":"けいけんをつむ · Keiken o tsumu","meaning":"menambah pengalaman"},{"word":"後輩","reading":"こうはい · Kouhai","meaning":"adik kelas/junior"},{"word":"相談に乗る","reading":"そうだんにのる · Soudan ni noru","meaning":"menampung konsultasi"},{"word":"資格","reading":"しかく · Shikaku","meaning":"sertifikasi/kualifikasi"}]'::jsonb, false),
(4, 'Meminta Kenaikan Gaji', 'biz',
 '[{"speaker":"アリ","text":"お時間をいただき、ありがとうございます。給与について相談がございます。","reading":"おじかんをいただき、ありがとうございます。きゅうよについてそうだんがございます。","romaji":"Ojikan o itadaki, arigatou gozaimasu. Kyuuyo ni tsuite soudan ga gozaimasu.","trans":"Terima kasih atas waktunya. Ada hal yang ingin saya konsultasikan soal gaji."},{"speaker":"部長","text":"はい、どうぞ話してください。","reading":"はい、どうぞはなしてください。","romaji":"Hai, douzo hanashite kudasai.","trans":"Ya, silakan bicara."},{"speaker":"アリ","text":"この一年で成果を上げてきたつもりです。評価していただけないでしょうか。","reading":"このいちねんでせいかをあげてきたつもりです。ひょうかしていただけないでしょうか。","romaji":"Kono ichinen de seika o agete kita tsumori desu. Hyouka shite itadakenai deshou ka.","trans":"Saya merasa telah memberi hasil selama setahun ini. Bisakah dipertimbangkan?"},{"speaker":"部長","text":"分かりました。検討してみます。","reading":"わかりました。けんとうしてみます。","romaji":"Wakarimashita. Kentou shite mimasu.","trans":"Baik. Akan saya pertimbangkan."},{"speaker":"アリ","text":"具体的には、今期の売上を二割伸ばしたことと、新しい取引先を三社開拓したことがあります。","reading":"ぐたいてきには、こんきのうりあげをにわりのばしたことと、あたらしいとりひきさきをさんしゃかいたくしたことがあります。","romaji":"Gutaiteki ni wa, konki no uriage o niwari nobashita koto to, atarashii torihikisaki o sansha kaitakushita koto ga arimasu.","trans":"Secara konkret, saya menaikkan penjualan periode ini sebesar dua puluh persen dan membuka tiga perusahaan mitra baru."},{"speaker":"部長","text":"確かに頑張ってくれているね。ただ、会社の予算にも限りがあるから、すぐには決められないよ。","reading":"たしかにがんばってくれているね。ただ、かいしゃのよさんにもかぎりがあるから、すぐにはきめられないよ。","romaji":"Tashikani ganbatte kurete iru ne. Tada, kaisha no yosan nimo kagiri ga aru kara, sugu ni wa kimerarenai yo.","trans":"Memang kamu sudah berusaha keras. Tapi anggaran perusahaan juga terbatas, jadi tidak bisa langsung diputuskan."},{"speaker":"アリ","text":"はい、承知しております。来月の評価面談までにお返事をいただけると助かります。","reading":"はい、しょうちしております。らいげつのひょうかめんだんまでにおへんじをいただけるとたすかります。","romaji":"Hai, shouchi shite orimasu. Raigetsu no hyoukamendan made ni ohenji o itadakeru to tasukarimasu.","trans":"Ya, saya mengerti. Akan sangat membantu jika saya bisa menerima jawaban sebelum wawancara penilaian bulan depan."},{"speaker":"部長","text":"分かった。それまでに人事部と相談しておくよ。","reading":"わかった。それまでにじんじぶとそうだんしておくよ。","romaji":"Wakatta. Sore made ni jinjibu to soudan shite oku yo.","trans":"Mengerti. Sampai saat itu saya akan berkonsultasi dengan bagian personalia."},{"speaker":"アリ","text":"ありがとうございます。今後も会社に貢献できるよう、努力してまいります。","reading":"ありがとうございます。こんごもかいしゃにこうけんできるよう、どりょくしてまいります。","romaji":"Arigatou gozaimasu. Kongo mo kaisha ni kouken dekiru you, doryoku shite mairimasu.","trans":"Terima kasih. Ke depan pun saya akan berusaha agar bisa berkontribusi bagi perusahaan."},{"speaker":"部長","text":"期待しているよ。引き続きよろしく頼む。","reading":"きたいしているよ。ひきつづきよろしくたのむ。","romaji":"Kitai shite iru yo. Hikitsuzuki yoroshiku tanomu.","trans":"Saya berharap padamu. Mohon terus bekerja sama seperti sebelumnya."}]'::jsonb,
 '[{"word":"給与","reading":"きゅうよ · Kyuuyo","meaning":"gaji"},{"word":"成果","reading":"せいか · Seika","meaning":"hasil/pencapaian"},{"word":"評価","reading":"ひょうか · Hyouka","meaning":"penilaian"},{"word":"開拓","reading":"かいたく · Kaitaku","meaning":"membuka/merintis (pasar)"},{"word":"予算","reading":"よさん · Yosan","meaning":"anggaran"},{"word":"貢献","reading":"こうけん · Kouken","meaning":"kontribusi"}]'::jsonb, false),
(4, 'Meminta Maaf atas Kesalahan', 'biz',
 '[{"speaker":"アリ","text":"先日の件で、こちらの確認不足によりご迷惑をおかけしました。","reading":"せんじつのけんで、こちらのかくにんぶそくによりごめいわくをおかけしました。","romaji":"Senjitsu no ken de, kochira no kakunin busoku ni yori gomeiwaku o okake shimashita.","trans":"Mengenai hal tempo hari, karena kurangnya pengecekan kami, kami telah merepotkan Anda."},{"speaker":"取引先","text":"いえいえ、誰にでもミスはありますから。","reading":"いえいえ、だれにでもミスはありますから。","romaji":"Ie ie, dare ni demo misu wa arimasu kara.","trans":"Tidak apa-apa, siapa pun bisa membuat kesalahan."},{"speaker":"アリ","text":"今後はこのようなことがないよう、十分注意いたします。","reading":"こんごはこのようなことがないよう、じゅうぶんちゅういいたします。","romaji":"Kongo wa kono you na koto ga nai you, juubun chuui itashimasu.","trans":"Ke depan kami akan sangat berhati-hati agar hal seperti ini tidak terjadi."},{"speaker":"取引先","text":"よろしくお願いします。","reading":"よろしくおねがいします。","romaji":"Yoroshiku onegaishimasu.","trans":"Mohon kerja samanya."},{"speaker":"取引先","text":"ところで、原因は何だったのですか。","reading":"ところで、げんいんはなにだったのですか。","romaji":"Tokorode, genin wa nani datta no desu ka.","trans":"Omong-omong, apa penyebabnya?"},{"speaker":"アリ","text":"発注書の数字を入力するときに、確認を怠ったことが原因です。","reading":"はっちゅうしょのすうじをにゅうりょくするときに、かくにんをおこたったことがげんいんです。","romaji":"Hatchuusho no suuji o nyuuryoku suru toki ni, kakunin o okotatta koto ga genin desu.","trans":"Penyebabnya adalah saya lalai memeriksa saat memasukkan angka pada surat pemesanan."},{"speaker":"取引先","text":"そうですか。商品はいつ届きますか。","reading":"そうですか。しょうひんはいつとどきますか。","romaji":"Sou desu ka. Shouhin wa itsu todokimasu ka.","trans":"Begitu. Kapan barangnya akan sampai?"},{"speaker":"アリ","text":"本日中に正しい数量を手配し、明後日までにお届けいたします。","reading":"ほんじつちゅうにただしいすうりょうをてはいし、あさってまでにおとどけいたします。","romaji":"Honjitsuchuu ni tadashii suuryou o tehai shi, asatte made ni otodoke itashimasu.","trans":"Hari ini juga kami akan mengatur jumlah yang benar, dan mengirimkannya paling lambat lusa."},{"speaker":"取引先","text":"助かります。同じことがないように、お願いしますね。","reading":"たすかります。おなじことがないように、おねがいしますね。","romaji":"Tasukarimasu. Onaji koto ga nai you ni, onegaishimasu ne.","trans":"Terima kasih, itu membantu. Tolong pastikan hal yang sama tidak terulang."},{"speaker":"アリ","text":"はい、今後はダブルチェックを徹底いたします。重ねてお詫び申し上げます。","reading":"はい、こんごはダブルチェックをてっていいたします。かさねておわびもうしあげます。","romaji":"Hai, kongo wa daburuchekku o tettei itashimasu. Kasanete owabi moushiagemasu.","trans":"Baik, ke depan kami akan menerapkan pemeriksaan ganda dengan tegas. Sekali lagi kami mohon maaf."}]'::jsonb,
 '[{"word":"確認不足","reading":"かくにんぶそく · Kakuninbusoku","meaning":"kurang pengecekan"},{"word":"迷惑をかける","reading":"めいわくをかける · Meiwaku o kakeru","meaning":"merepotkan"},{"word":"注意","reading":"ちゅうい · Chuui","meaning":"berhati-hati"},{"word":"原因","reading":"げんいん · Genin","meaning":"penyebab"},{"word":"手配","reading":"てはい · Tehai","meaning":"mengatur/mengurus (pengiriman dsb.)"},{"word":"徹底","reading":"てってい · Tettei","meaning":"menerapkan secara menyeluruh"}]'::jsonb, false),
(4, 'Menanggapi Keluhan Pelanggan', 'work',
 '[{"speaker":"客","text":"注文した商品がまだ届かないんですが。","reading":"ちゅうもんしたしょうひんがまだとどかないんですが。","romaji":"Chuumon shita shouhin ga mada todokanai n desu ga.","trans":"Barang yang saya pesan belum sampai juga."},{"speaker":"アリ","text":"ご不便をおかけして申し訳ございません。すぐに確認いたします。","reading":"ごふべんをおかけしてもうしわけございません。すぐにかくにんいたします。","romaji":"Gofuben o okake shite moushiwake gozaimasen. Sugu ni kakunin itashimasu.","trans":"Mohon maaf atas ketidaknyamanannya. Akan segera saya periksa."},{"speaker":"客","text":"早めにお願いします。","reading":"はやめにおねがいします。","romaji":"Hayame ni onegaishimasu.","trans":"Tolong secepatnya."},{"speaker":"アリ","text":"本日中にご連絡いたします。","reading":"ほんじつちゅうにごれんらくいたします。","romaji":"Honjitsu-chuu ni gorenraku itashimasu.","trans":"Saya akan menghubungi dalam hari ini."},{"speaker":"客","text":"今日中ですか。実は、来週の引っ越しに間に合わないと困るんです。","reading":"きょうじゅうですか。じつは、らいしゅうのひっこしにまにあわないとこまるんです。","romaji":"Kyoujuu desu ka. Jitsu wa, raishuu no hikkoshi ni maniawanai to komaru n desu.","trans":"Hari ini juga? Sebenarnya, saya akan kesulitan kalau tidak sampai sebelum pindahan minggu depan."},{"speaker":"アリ","text":"それは大変失礼いたしました。お急ぎの件でしたら、配送状況を最優先で調べます。","reading":"それはたいへんしつれいいたしました。おいそぎのけんでしたら、はいそうじょうきょうをさいゆうせんでしらべます。","romaji":"Sore wa taihen shitsurei itashimashita. Oisogi no ken deshitara, haisoujoukyou o saiyuusen de shirabemasu.","trans":"Itu sungguh tidak sopan dari kami. Kalau urusannya mendesak, akan saya periksa status pengiriman dengan prioritas utama."},{"speaker":"客","text":"お願いします。電話番号は先ほどお伝えしたものです。","reading":"おねがいします。でんわばんごうはさきほどおつたえしたものです。","romaji":"Onegaishimasu. Denwabangou wa sakihodo otsutae shita mono desu.","trans":"Tolong ya. Nomor telepon saya yang tadi sudah saya sampaikan."},{"speaker":"アリ","text":"かしこまりました。確認でき次第、こちらからお電話いたします。","reading":"かしこまりました。かくにんできしだい、こちらからおでんわいたします。","romaji":"Kashikomarimashita. Kakunin deki shidai, kochira kara odenwa itashimasu.","trans":"Baik. Begitu sudah terkonfirmasi, kami sendiri yang akan menelepon Anda."},{"speaker":"客","text":"分かりました。待っています。","reading":"わかりました。まっています。","romaji":"Wakarimashita. Matte imasu.","trans":"Mengerti. Saya tunggu."},{"speaker":"アリ","text":"ご不明な点がございましたら、いつでもお申し付けください。","reading":"ごふめいなてんがございましたら、いつでもおもうしつけください。","romaji":"Go fumei na ten ga gozaimashitara, itsudemo omoushitsuke kudasai.","trans":"Jika ada hal yang kurang jelas, silakan beri tahu kami kapan saja."}]'::jsonb,
 '[{"word":"商品","reading":"しょうひん · Shouhin","meaning":"barang/produk"},{"word":"不便","reading":"ふべん · Fuben","meaning":"ketidaknyamanan"},{"word":"確認","reading":"かくにん · Kakunin","meaning":"konfirmasi"},{"word":"配送","reading":"はいそう · Haisou","meaning":"pengiriman"},{"word":"最優先","reading":"さいゆうせん · Saiyuusen","meaning":"prioritas utama"},{"word":"次第","reading":"しだい · Shidai","meaning":"begitu/segera setelah (V-masu + 次第)"}]'::jsonb, false),
(4, 'Negosiasi dengan Klien', 'biz',
 '[{"speaker":"取引先","text":"納期を一週間早めていただくことは可能でしょうか。","reading":"のうきをいっしゅうかんはやめていただくことはかのうでしょうか。","romaji":"Nouki o isshuukan hayamete itadaku koto wa kanou deshou ka.","trans":"Apakah memungkinkan untuk mempercepat tenggat satu minggu?"},{"speaker":"アリ","text":"社内で検討いたしますが、品質の面で少々厳しいかもしれません。","reading":"しゃないでけんとういたしますが、ひんしつのめんでしょうしょうきびしいかもしれません。","romaji":"Shanai de kentou itashimasu ga, hinshitsu no men de shoushou kibishii kamoshiremasen.","trans":"Akan kami pertimbangkan secara internal, tapi dari segi kualitas mungkin agak sulit."},{"speaker":"取引先","text":"そうですか。では、できる範囲で結構です。","reading":"そうですか。では、できるはんいでけっこうです。","romaji":"Sou desu ka. Dewa, dekiru han''i de kekkou desu.","trans":"Begitu ya. Kalau begitu, sebatas yang bisa pun tidak masalah."},{"speaker":"アリ","text":"承知しました。改めてご連絡いたします。","reading":"しょうちしました。あらためてごれんらくいたします。","romaji":"Shouchi shimashita. Aratamete gorenraku itashimasu.","trans":"Baik, kami mengerti. Kami akan menghubungi kembali."},{"speaker":"取引先","text":"実は、他社からも見積もりをもらっていまして。もう少し価格を抑えられませんか。","reading":"じつは、たしゃからもみつもりをもらっていまして。もうすこしかかくをおさえられませんか。","romaji":"Jitsu wa, tasha karamo mitsumori o moratte imashite. Mou sukoshi kakaku o osaeraremasen ka.","trans":"Sebenarnya kami juga menerima penawaran dari perusahaan lain. Tidak bisakah harganya ditekan sedikit lagi?"},{"speaker":"アリ","text":"価格につきましては、数量を増やしていただければ、単価をお下げできるかもしれません。","reading":"かかくにつきましては、すうりょうをふやしていただければ、たんかをおさげできるかもしれません。","romaji":"Kakaku ni tsukimashite wa, suuryou o fuyashite itadakereba, tanka o osage dekiru kamo shiremasen.","trans":"Soal harga, jika jumlah pesanan ditambah, mungkin harga satuan bisa kami turunkan."},{"speaker":"取引先","text":"なるほど。何個以上なら割引になりますか。","reading":"なるほど。なんこいじょうならわりびきになりますか。","romaji":"Naruhodo. Nanko ijou nara waribiki ni narimasu ka.","trans":"Begitu. Kalau minimal berapa buah, bisa dapat diskon?"},{"speaker":"アリ","text":"千個以上のご注文でしたら、五パーセント値引きいたします。","reading":"せんこいじょうのごちゅうもんでしたら、ごパーセントねびきいたします。","romaji":"Senko ijou no go chuumon deshitara, go paasento nebiki itashimasu.","trans":"Untuk pesanan seribu buah ke atas, kami beri potongan lima persen."},{"speaker":"取引先","text":"それなら社内で相談してみます。来週中にお返事します。","reading":"それならしゃないでそうだんしてみます。らいしゅうちゅうにおへんじします。","romaji":"Sorenara shanai de soudan shite mimasu. Raishuuchuu ni ohenji shimasu.","trans":"Kalau begitu, akan saya coba bicarakan di internal. Saya akan memberi jawaban dalam minggu depan."},{"speaker":"アリ","text":"ありがとうございます。良いお返事をお待ちしております。","reading":"ありがとうございます。よいおへんじをおまちしております。","romaji":"Arigatou gozaimasu. Yoi ohenji o omachi shite orimasu.","trans":"Terima kasih. Kami menantikan jawaban yang baik."}]'::jsonb,
 '[{"word":"納期","reading":"のうき · Nouki","meaning":"tenggat/deadline pengiriman"},{"word":"検討","reading":"けんとう · Kentou","meaning":"mempertimbangkan"},{"word":"承知","reading":"しょうち · Shouchi","meaning":"mengerti (sopan)"},{"word":"見積もり","reading":"みつもり · Mitsumori","meaning":"penawaran harga"},{"word":"単価","reading":"たんか · Tanka","meaning":"harga satuan"},{"word":"値引き","reading":"ねびき · Nebiki","meaning":"potongan harga"}]'::jsonb, false)

ON CONFLICT (level_id, title) DO UPDATE SET
  lines = EXCLUDED.lines,
  vocab_highlight = EXCLUDED.vocab_highlight;
